import {PGlite} from '@electric-sql/pglite';
import {readFile,writeFile} from 'node:fs/promises';
import assert from 'node:assert/strict';
const db=new PGlite();
await db.exec(`CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth; CREATE SCHEMA storage;
CREATE TABLE auth.users(id uuid PRIMARY KEY,email text UNIQUE,email_confirmed_at timestamptz);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
GRANT USAGE ON SCHEMA auth,storage TO authenticated,anon; GRANT EXECUTE ON FUNCTION auth.uid() TO authenticated,anon;
CREATE TABLE storage.buckets(id text PRIMARY KEY,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
CREATE TABLE storage.objects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bucket_id text,name text);
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY; GRANT SELECT,INSERT,UPDATE,DELETE ON storage.objects TO authenticated;
CREATE FUNCTION storage.foldername(name text) RETURNS text[] LANGUAGE sql AS $$ SELECT (string_to_array(name,'/'))[1:array_length(string_to_array(name,'/'),1)-1] $$;`);
await db.exec(await readFile(new URL('../../supabase/migrations/20261112000000_schema_v1.sql',import.meta.url),'utf8'));
const uuid=n=>`00000000-0000-4000-8000-${String(n).padStart(12,'0')}`;
const owner=uuid(1),lead=uuid(2),mover=uuid(3),other=uuid(4),outsider=uuid(5),unverified=uuid(6);
await db.exec(`INSERT INTO auth.users VALUES ('${owner}','move@themoverz.com',now()),('${lead}','lead@example.test',now()),('${mover}','mover@example.test',now()),('${other}','other@example.test',now()),('${outsider}','outsider@example.test',now()),('${unverified}','unverified@example.test',NULL)`);
const company=(await db.query("select id from public.companies where slug='the-movers'")).rows[0].id;
const company2=uuid(20),j1=uuid(30),j2=uuid(31),j3=uuid(32),customer=uuid(40),customer2=uuid(41);
async function asUser(id,sql,params=[]){await db.exec('BEGIN');try{await db.query("select set_config('request.jwt.claim.sub',$1,true)",[id??'']);await db.exec('SET LOCAL ROLE authenticated');const result=await db.query(sql,params);await db.exec('COMMIT');return result}catch(e){await db.exec('ROLLBACK');throw e}}
const checks=[];async function test(name,fn){await fn();checks.push(name)};
await test('Verified initial owner can claim The Movers',async()=>{const r=await asUser(owner,'select public.claim_initial_owner() as id');assert.equal(r.rows[0].id,company)});
await test('Wrong email cannot claim company ownership',async()=>assert.rejects(asUser(outsider,'select public.claim_initial_owner()')));
await test('Unverified account cannot claim ownership',async()=>assert.rejects(asUser(unverified,'select public.claim_initial_owner()')));
await test('Owner can register a verified crew leader',async()=>{await asUser(owner,'select public.set_company_member($1,$2,$3,$4)',[company,'lead@example.test','Leader','crew_leader'])});
await asUser(owner,'select public.set_company_member($1,$2,$3,$4)',[company,'mover@example.test','Mover','mover']);
await db.exec(`INSERT INTO public.companies(id,name,slug) VALUES('${company2}','Other Moving Company','other-movers'); INSERT INTO public.company_members(company_id,user_id,display_name,role) VALUES('${company2}','${other}','Other owner','owner');
INSERT INTO public.customers(id,company_id,name,office_notes) VALUES('${customer}','${company}','Customer A','Private sales information'),('${customer2}','${company2}','Customer B','Other company notes');
INSERT INTO public.jobs(id,company_id,customer_id,customer_name,move_date,pick_up_address,drop_off_address,move_type,status,crew_size,pricing_model,hourly_rate_cents,service_charge_cents) VALUES
('${j1}','${company}','${customer}','Assigned customer','2027-12-31','Pick-up A','Drop-off A','residential','booked',2,'hourly',11000,12500),
('${j2}','${company}','${customer}','Unassigned customer','2027-12-30','Pick-up B','Drop-off B','residential','booked',2,'hourly',11000,12500),
('${j3}','${company2}','${customer2}','Other company customer','2027-12-31','Pick-up C','Drop-off C','residential','booked',2,'hourly',11000,12500);
INSERT INTO public.job_assignments VALUES('${company}','${j1}','${lead}','Leader'),('${company}','${j1}','${mover}','Mover');
INSERT INTO public.job_office_notes VALUES('${company}','${j1}','Internal margin and sales notes');`);
await test('Mover sees future assigned job only',async()=>{const r=await asUser(mover,'select id from public.jobs');assert.deepEqual(r.rows.map(r=>r.id),[j1])});
await test('Crew cannot read customer records or office notes',async()=>{assert.equal((await asUser(mover,'select * from public.customers')).rows.length,0);assert.equal((await asUser(lead,'select * from public.job_office_notes')).rows.length,0)});
await test('Crew cannot edit customer-facing job details',async()=>{const r=await asUser(mover,"update public.jobs set customer_name='Changed' where id=$1 returning id",[j1]);assert.equal(r.rows.length,0)});
await test('Crew cannot assign themselves another job',async()=>assert.rejects(asUser(mover,'insert into public.job_assignments values($1,$2,$3,$4)',[company,j2,mover,'Mover'])));
await test('Crew cannot grant themselves a role',async()=>{await assert.rejects(asUser(mover,"update public.company_members set role='owner' where user_id=$1",[mover]));await assert.rejects(asUser(mover,'select public.set_company_member($1,$2,$3,$4)',[company,'mover@example.test','Mover','owner']))});
await test('Same-company owner sees all own jobs but no other company jobs',async()=>{const rows=(await asUser(owner,'select id from public.jobs order by id')).rows.map(r=>r.id);assert.deepEqual(rows,[j1,j2])});
await test('Another company owner cannot see The Movers data',async()=>{assert.deepEqual((await asUser(other,'select id from public.jobs')).rows.map(r=>r.id),[j3])});
await test('Cross-company customer links are rejected',async()=>assert.rejects(asUser(owner,"insert into public.jobs(company_id,customer_id,customer_name,move_date,pick_up_address,drop_off_address,move_type,crew_size,pricing_model,flat_rate_cents) values($1,$2,'Bad link','2027-01-01','A','B','residential',2,'flat',10000)",[company,customer2])));
await test('Mover can record their own time',async()=>{await asUser(mover,"insert into public.time_entries(company_id,job_id,started_at) values($1,$2,'2027-12-31T08:00Z')",[company,j1])});
await test('Mover cannot record another person’s time',async()=>assert.rejects(asUser(mover,"insert into public.time_entries(company_id,job_id,user_id,started_at) values($1,$2,$3,'2027-12-31T08:00Z')",[company,j1,lead])));
await test('Mover cannot record time on an unassigned job',async()=>assert.rejects(asUser(mover,"insert into public.time_entries(company_id,job_id,started_at) values($1,$2,'2027-12-31T08:00Z')",[company,j2])));
await test('Mover cannot record a payment',async()=>assert.rejects(asUser(mover,"insert into public.payment_records(company_id,job_id,method,amount_cents,payment_date) values($1,$2,'cash',5000,'2027-12-31')",[company,j1])));
await test('Assigned leader can report a cash payment',async()=>{await asUser(lead,"insert into public.payment_records(company_id,job_id,method,amount_cents,payment_date) values($1,$2,'cash',5025,'2027-12-31')",[company,j1])});
await test('Leader cannot mark a payment confirmed',async()=>{assert.equal((await asUser(lead,"update public.payment_records set status='confirmed' returning id")).rows.length,0);await assert.rejects(asUser(lead,"insert into public.payment_records(company_id,job_id,method,amount_cents,payment_date,status) values($1,$2,'zelle',5000,'2027-12-31','confirmed')",[company,j1]))});
await test('A check number is required',async()=>assert.rejects(asUser(lead,"insert into public.payment_records(company_id,job_id,method,amount_cents,payment_date) values($1,$2,'check',5000,'2027-12-31')",[company,j1])));
await test('Owner can confirm a reported payment',async()=>{assert.equal((await asUser(owner,"update public.payment_records set status='confirmed' returning id")).rows.length,1)});
await test('Crew cannot read other members’ membership rows',async()=>{assert.equal((await asUser(mover,'select * from public.company_members')).rows.length,1)});
const ownPath=`${company}/${j1}/${mover}/condition.jpg`;
await test('Assigned mover can upload a private job photo',async()=>{await asUser(mover,"insert into storage.objects(bucket_id,name) values('job-photos',$1)",[ownPath])});
await test('Another company cannot read the job photo',async()=>{assert.equal((await asUser(other,'select * from storage.objects')).rows.length,0)});
await test('Uploads to unassigned jobs or another user’s folder fail',async()=>{await assert.rejects(asUser(mover,"insert into storage.objects(bucket_id,name) values('job-photos',$1)",[`${company}/${j2}/${mover}/bad.jpg`]));await assert.rejects(asUser(mover,"insert into storage.objects(bucket_id,name) values('job-photos',$1)",[`${company}/${j1}/${lead}/bad.jpg`]))});
await test('Client cannot overwrite a stored photo',async()=>{assert.equal((await asUser(mover,"update storage.objects set name='replacement' returning id")).rows.length,0)});
await test('Owner can deactivate a member and access stops',async()=>{await asUser(owner,'select public.set_company_member($1,$2,$3,$4,false)',[company,'mover@example.test','Mover','mover']);assert.equal((await asUser(mover,'select * from public.jobs')).rows.length,0);assert.equal((await asUser(mover,'select * from storage.objects')).rows.length,0)});
await test('Unsigned requests cannot retrieve jobs',async()=>{await db.exec('BEGIN; SET LOCAL ROLE anon;');try{await assert.rejects(db.query('select * from public.jobs'))}finally{await db.exec('ROLLBACK')}});
await test('Unknown signed-in account has no company access',async()=>{assert.equal((await asUser(outsider,'select * from public.jobs')).rows.length,0)});
await test('The Movers pricing defaults match requirements',async()=>{const rows=(await asUser(owner,'select crew_size,weekday_rate_cents,weekend_rate_cents,service_base_cents from public.crew_rates order by crew_size')).rows;assert.deepEqual(rows.map(r=>[r.crew_size,Number(r.weekday_rate_cents),Number(r.weekend_rate_cents),Number(r.service_base_cents)]),[[2,11000,12000,7500],[3,13500,15000,9500],[4,18000,20000,14500]])});

await db.exec(await readFile(new URL('../../supabase/migrations/20261114000000_estimates.sql',import.meta.url),'utf8'));
await db.exec(await readFile(new URL('../../supabase/migrations/20261114000000_estimates.sql',import.meta.url),'utf8'));
const payload={customer_name:'Estimate Customer',email:'test@example.test',phone:'555',move_date:'2026-11-16',pick_up_address:'A',drop_off_address:'B',move_type:'residential',crew_size:2,pricing_model:'hourly',estimated_minutes:121,round_trip_miles:40};
const save=(user,p=payload,co=company)=>asUser(user,'select public.save_estimate($1,$2::jsonb) as id',[co,JSON.stringify(p)]);
let estimate;
await test('Owner can atomically save estimate at correct price',async()=>{estimate=(await save(owner)).rows[0].id;const x=(await asUser(owner,'select * from public.jobs where id=$1',[estimate])).rows[0];assert.equal(Number(x.quoted_total_cents),37250);assert.equal(Number(x.service_charge_cents),12500);assert.equal(Number(x.deposit_required_cents),5000)});
await test('Missing mileage is rejected',async()=>assert.rejects(save(owner,{...payload,round_trip_miles:null})));
await test('Mismatched tenant customer is rejected',async()=>assert.rejects(save(owner,{...payload,customer_id:customer2})));
await test('Crew cannot invoke estimate RPC',async()=>assert.rejects(save(lead)));
await test('Other company owner cannot save in The Movers',async()=>assert.rejects(save(other)));
await test('Unregistered account cannot invoke estimate RPC',async()=>assert.rejects(save(outsider)));
await test('Invalid move type rolls back customer insert too',async()=>{const before=(await asUser(owner,'select count(*) from public.customers')).rows[0].count;await assert.rejects(save(owner,{...payload,move_type:'invalid'}));assert.equal((await asUser(owner,'select count(*) from public.customers')).rows[0].count,before)});
await test('Existing customer is reused without duplicate',async()=>{const before=(await asUser(owner,'select count(*) from public.customers')).rows[0].count;await save(owner,{...payload,customer_id:customer});assert.equal((await asUser(owner,'select count(*) from public.customers')).rows[0].count,before)});
await test('Edit keeps same job and updates flat quote with 50 percent deposit',async()=>{await save(owner,{...payload,id:estimate,pricing_model:'flat',flat_rate_cents:100001,out_of_town:true});const x=(await asUser(owner,'select * from public.jobs where id=$1',[estimate])).rows[0];assert.equal(Number(x.quoted_total_cents),100001);assert.equal(Number(x.deposit_required_cents),50001);assert.equal(Number(x.service_charge_cents),0)});
await test('Hourly long distance is rejected',async()=>assert.rejects(save(owner,{...payload,out_of_town:true})));
await test('Weekend rate is used and client totals are ignored',async()=>{const id=(await save(owner,{...payload,move_date:'2026-11-15',quoted_total_cents:1})).rows[0].id;const x=(await asUser(owner,'select * from public.jobs where id=$1',[id])).rows[0];assert.equal(Number(x.hourly_rate_cents),12000);assert.equal(Number(x.quoted_total_cents),39500)});
await test('Booked job is protected from estimate editor',async()=>{await asUser(owner,"update public.jobs set status='booked' where id=$1",[estimate]);await assert.rejects(save(owner,{...payload,id:estimate}))});
await test('New estimate remains invisible to unassigned crew',async()=>assert.equal((await asUser(lead,'select id from public.jobs where id=$1',[estimate])).rows.length,0));

await db.exec(await readFile(new URL('../../supabase/migrations/20261114230000_dispatch.sql',import.meta.url),'utf8'));
await db.exec(await readFile(new URL('../../supabase/migrations/20261114230000_dispatch.sql',import.meta.url),'utf8'));
// Reenable the mover deactivated by the original permission checks.
await asUser(owner,'select public.set_company_member($1,$2,$3,$4,true)',[company,'mover@example.test','Mover','mover']);
const trucks=(await asUser(owner,'select * from public.trucks order by name')).rows;
const details=async(id)=> (await asUser(owner,'select * from public.jobs where id=$1',[id])).rows[0];
const makeBooked=async(p={})=>{const id=(await save(owner,{...payload,...p})).rows[0].id;await asUser(owner,"update public.jobs set status='booked' where id=$1",[id]);return id};
const dispatch=async(user,id,extra={})=>{const old=await details(id);return asUser(user,'select public.save_dispatch_job($1,$2::jsonb)',[company,JSON.stringify({...payload,id,row_version:old.row_version,arrival_time:'09:00',scheduled_minutes:180,truck_id:trucks[0].id,crew_ids:[lead,mover],...extra})])};
const a=await makeBooked();
await test('Booked details can be edited with truck and crew atomically',async()=>{await dispatch(owner,a,{customer_name:'Edited job'});const x=await details(a);assert.equal(x.customer_name,'Edited job');assert.equal(x.truck_id,trucks[0].id);assert.equal(x.scheduled_minutes,180);assert.equal((await asUser(owner,'select * from public.job_assignments where job_id=$1',[a])).rows.length,2)});
await test('Crew sees assigned booked job immediately',async()=>assert.equal((await asUser(lead,'select id from public.jobs where id=$1',[a])).rows.length,1));
await test('Crew and other tenant cannot edit dispatch job',async()=>{await assert.rejects(dispatch(lead,a));await assert.rejects(dispatch(other,a))});
const b=await makeBooked();
await test('Overlapping truck assignment rejected and details rolled back',async()=>{await assert.rejects(dispatch(owner,b,{customer_name:'Should rollback',crew_ids:[]}));assert.equal((await details(b)).customer_name,payload.customer_name);assert.equal((await details(b)).truck_id,null)});
await test('Overlapping crew on a different truck is rejected',async()=>assert.rejects(dispatch(owner,b,{truck_id:trucks[1].id})));
await test('Back-to-back assignments are allowed',async()=>{await dispatch(owner,b,{arrival_time:'12:00'})});
await test('Moving a job to another day retains job identity and assignments',async()=>{await dispatch(owner,b,{move_date:'2026-11-17'});assert.equal((await details(b)).move_date.toISOString().slice(0,10),'2026-11-17');assert.equal((await asUser(owner,'select * from public.job_assignments where job_id=$1',[b])).rows.length,2)});
await test('Stale browser version cannot overwrite a newer job',async()=>{const x=await details(b);await dispatch(owner,b,{move_date:'2026-11-17'});await assert.rejects(dispatch(owner,b,{row_version:x.row_version,move_date:'2026-11-18'}))});
await test('Assigned jobs require arrival time',async()=>assert.rejects(dispatch(owner,b,{arrival_time:''})));
await test('Invalid duration is rejected',async()=>assert.rejects(dispatch(owner,b,{scheduled_minutes:0})));
await test('Cannot exceed quoted crew size',async()=>assert.rejects(dispatch(owner,b,{crew_ids:[lead,mover,other]})));
await test('Foreign company crew and trucks are rejected',async()=>{await assert.rejects(dispatch(owner,b,{crew_ids:[other]}));await db.query("insert into public.trucks(company_id,name) values($1,'Foreign truck')",[company2]);const t=(await db.query('select id from public.trucks where company_id=$1',[company2])).rows[0].id;await assert.rejects(dispatch(owner,b,{truck_id:t}))});
await test('Read-only terminal jobs cannot be edited',async()=>{await asUser(owner,"update public.jobs set status='completed' where id=$1",[b]);await assert.rejects(dispatch(owner,b))});
await test('Crew cannot view fleet or create truck',async()=>{assert.equal((await asUser(lead,'select * from public.trucks')).rows.length,0);await assert.rejects(asUser(lead,"insert into public.trucks(company_id,name) values($1,'Bad')",[company]))});
await test('Stale cancel rejected; valid cancellation persists record',async()=>{const x=await details(a);await assert.rejects(asUser(owner,'select public.cancel_dispatch_job($1,$2,$3)',[company,a,x.row_version-1]));await asUser(owner,'select public.cancel_dispatch_job($1,$2,$3)',[company,a,x.row_version]);assert.equal((await details(a)).status,'cancelled')});
await test('Cancelled job releases its time and resources',async()=>{await dispatch(owner,await makeBooked())});
const night=await makeBooked({move_date:'2026-11-20'});await dispatch(owner,night,{move_date:'2026-11-20',arrival_time:'23:00',scheduled_minutes:180});
await test('Conflict check spans midnight',async()=>{const id=await makeBooked({move_date:'2026-11-21'});await assert.rejects(dispatch(owner,id,{move_date:'2026-11-21',arrival_time:'01:00'}))});
await test('Internal quote writer cannot be invoked by client role',async()=>assert.rejects(asUser(owner,'select app_private.write_job_quote($1,$2::jsonb)',[company,JSON.stringify(payload)])));
await test('Weekend rescheduling recalculates visible customer pricing',async()=>{const id=await makeBooked();await dispatch(owner,id,{move_date:'2026-11-22',arrival_time:'12:00',crew_ids:[],truck_id:''});assert.equal(Number((await details(id)).hourly_rate_cents),12000)});

await db.exec(await readFile(new URL('../../supabase/migrations/20261116000000_sms_connection.sql',import.meta.url),'utf8'));
await db.exec(await readFile(new URL('../../supabase/migrations/20261116000000_sms_connection.sql',import.meta.url),'utf8'));
const testPhone='+14695551234';
await test('SMS connection belongs to The Movers only',async()=>{assert.equal((await asUser(owner,'select * from public.sms_test_connections')).rows.length,1);assert.equal((await asUser(other,'select * from public.sms_test_connections')).rows.length,0);assert.equal((await asUser(lead,'select * from public.sms_test_connections')).rows.length,0)});
await test('Test phone is office-only and validates number',async()=>{await assert.rejects(asUser(lead,'select public.set_sms_test_phone($1,$2)',[company,testPhone]));await assert.rejects(asUser(other,'select public.set_sms_test_phone($1,$2)',[company,testPhone]));await assert.rejects(asUser(owner,'select public.set_sms_test_phone($1,$2)',[company,'4695551234']));await asUser(owner,'select public.set_sms_test_phone($1,$2)',[company,testPhone])});
const reserve=(who,request=uuid(80),co=company)=>asUser(who,'select public.reserve_sms_test($1,$2,$3) as value',[co,request,testPhone]);
let testMessage;
await test('Office can reserve one fixed-body test',async()=>{const r=(await reserve(owner)).rows[0].value;assert.equal(r.created,true);assert.equal(r.phone,testPhone);assert.ok(r.body.startsWith('The Movers:'));testMessage=r.id});
await test('Retrying same request cannot send a duplicate',async()=>{const r=(await reserve(owner)).rows[0].value;assert.equal(r.created,false);assert.equal(r.id,testMessage)});
await test('One-minute limit enforced',async()=>assert.rejects(reserve(owner,uuid(81))));
await test('Crew and another company cannot reserve tests',async()=>{await assert.rejects(reserve(lead));await assert.rejects(reserve(other));await assert.rejects(reserve(owner,uuid(81),company2))});
await test('Clients cannot insert logs or forge provider results',async()=>{await assert.rejects(asUser(owner,"insert into public.sms_test_messages(company_id,request_id,to_phone,body,direction,status) values($1,$2,$3,'Fake','outbound','delivered')",[company,uuid(89),testPhone]));await assert.rejects(asUser(owner,'select public.finish_sms_test($1,$2,$3)',[testMessage,'SM'+'1'.repeat(32),'delivered']))});
async function service(sql,args=[]){await db.exec('BEGIN; SET LOCAL ROLE service_role;');try{const r=await db.query(sql,args);await db.exec('COMMIT');return r}catch(e){await db.exec('ROLLBACK');throw e}}
const finish=(status)=>service('select public.finish_sms_test($1,$2,$3)',[testMessage,'SM'+'1'.repeat(32),status]);
await test('Provider progress cannot regress delivered status',async()=>{await finish('queued');await finish('delivered');await finish('sent');assert.equal((await asUser(owner,'select status from public.sms_test_messages where id=$1',[testMessage])).rows[0].status,'delivered')});
const inbound=(id,body,event)=>service('select public.record_sms_test_reply($1,$2,$3,$4,$5)',[company,'SM'+id.repeat(32),testPhone,body,event]);
await test('Signed inbound STOP records suppression',async()=>{await inbound('2','STOP','STOP');assert.equal((await asUser(owner,'select blocked from public.sms_suppressions')).rows[0].blocked,true)});
await db.query("update public.sms_test_messages set created_at=now()-interval '2 minutes' where id=$1",[testMessage]);
await test('Opted-out test number cannot receive another test',async()=>assert.rejects(reserve(owner,uuid(81))));
await test('Changing recipient and back does not erase STOP',async()=>{await asUser(owner,'select public.set_sms_test_phone($1,$2)',[company,'+14695551235']);await asUser(owner,'select public.set_sms_test_phone($1,$2)',[company,testPhone]);await assert.rejects(reserve(owner,uuid(81)))});
await test('START reenables number; duplicate old STOP webhook does not reverse it',async()=>{await inbound('3','START','START');await inbound('2','STOP','STOP');assert.equal((await asUser(owner,'select blocked from public.sms_suppressions')).rows[0].blocked,false);await reserve(owner,uuid(81))});
await test('Inbound messages are deduplicated by provider SID',async()=>{await inbound('4','Test reply',null);await inbound('4','Test reply',null);assert.equal((await asUser(owner,"select count(*) as n from public.sms_test_messages where provider_sid=$1",['SM'+'4'.repeat(32)])).rows[0].n,1)});
