await test('Switched-off add-ons cannot be added; bad quantities are refused',async()=>{const tape=(await items()).find(x=>x.name==='Tape');await assert.rejects(save(owner,{...pq,line_items:[{item_id:tape.id,quantity:1}]}),/not on the active price list/);await assert.rejects(save(owner,{...pq,line_items:[{item_id:piano.id,quantity:0}]}),/quantity/)});
await test('Manual service charge replaces the mileage formula; mileage can be left unknown',async()=>{const id=(await save(owner,{...pq,round_trip_miles:0,miles_unknown:true,service_charge_manual:true,manual_service_charge_cents:12500,line_items:[{item_id:piano.id,quantity:1}]})).rows[0].id;const j=await details(id);assert.equal(Number(j.service_charge_cents),12500);assert.equal(j.service_charge_manual,true);assert.equal(j.round_trip_miles,null);const labor=Math.round(Number(j.hourly_rate_cents)*135/60);assert.equal(Number(j.quoted_total_cents),labor+12500+15000);await assert.rejects(save(owner,{...pq,service_charge_manual:true,manual_service_charge_cents:null}),/service charge amount/)});
await test('Older app versions keep a manual service charge and add-ons when saving',async()=>{const id=(await save(owner,{...pq,move_date:'2027-09-22',round_trip_miles:0,miles_unknown:true,service_charge_manual:true,manual_service_charge_cents:9900,line_items:[{item_id:piano.id,quantity:1}]})).rows[0].id;const before=await details(id);await save(owner,{...pq,id,move_date:'2027-09-22',round_trip_miles:12});const after=await details(id);assert.equal(Number(after.service_charge_cents),9900);assert.equal(Number(after.add_ons_cents),15000);assert.equal(Number(after.quoted_total_cents),Number(before.quoted_total_cents))});
await test('Out-of-town deposit (50%) includes add-ons',async()=>{const id=(await save(owner,{...pq,move_date:'2027-10-01',out_of_town:true,pricing_model:'flat',flat_rate_cents:200000,line_items:[{item_id:piano.id,quantity:2}]})).rows[0].id;const j=await details(id);assert.equal(Number(j.quoted_total_cents),230000);assert.equal(Number(j.deposit_required_cents),115000)});
